const original = $('input').first().json.original_input;
const ctx = $('Formatear historial').first().json;
let prev = {};
try { prev = JSON.parse(ctx.datos_clave || '{}'); } catch (e) {}

const raw = $json.text ?? $json.output ?? $json.response ?? '';
let d;
try {
  d = JSON.parse(String(raw).replace(/^```json\s*/i,'').replace(/```$/,'').trim());
} catch (e) {
  d = { intent:'UNKNOWN', confidence:0, risk:'HIGH' };
}
const allowed = ['FACTURACION','SOPORTE','HORAS','RESUMEN','UNKNOWN'];
const intent = allowed.includes(d.intent) ? d.intent : 'UNKNOWN';
const confidence = Math.max(0, Math.min(1, Number(d.confidence ?? 0)));
const risk = ['LOW','MEDIUM','HIGH'].includes(d.risk) ? d.risk : 'HIGH';

// Nunca pisar un dato conocido con vacío
const pick = (nuevo, viejo) => String(nuevo ?? '').trim() || String(viejo ?? '').trim();
const nombre   = pick(d.nombre, prev.nombre) || ctx.user_name || '';
const client   = pick(d.client, prev.cliente);
const problema = pick(d.problema, prev.problema);
const es_continuacion = Boolean(d.es_continuacion);

const datos_clave = JSON.stringify({ nombre, cliente: client, problema, ultimo_intent: intent });

const contexto = [
  `Usuario: ${nombre || 'desconocido'}`,
  client   && `Cliente: ${client}`,
  problema && `Problema en curso: ${problema}`,
  ctx.last_summary && `Resumen previo: ${ctx.last_summary}`,
  `Últimas interacciones:\n${ctx.historial_previo}`,
].filter(Boolean).join('\n');

const mensaje_contextualizado = `${contexto}\n\nMENSAJE ACTUAL DEL USUARIO:\n${original}`;

return [{ json: {
  original_input: original,
  mensaje_contextualizado,
  intent, confidence, risk, client,
  nombre, problema, es_continuacion, datos_clave,
}}];

const hitl = $('Edit Fields').isExecuted;
return $input.all().map(item => ({json:{
  timestamp: new Date().toISOString(),
  status: item.json.status ?? 'success',
  worker: item.json.worker ?? 'N/D',
  respuesta: item.json.respuesta || 'No pude generar una respuesta. Probá reformular tu consulta.',
  requires_human: Boolean(item.json.requires_human) || hitl,
}}));

// Lee el registro de Airtable (aplanado o en .fields) y arma el contexto
const getVal = (fn) => { try { return fn(); } catch { return undefined; } };

const tg = getVal(() => $('Telegram Trigger').first().json.message.from)
        ?? getVal(() => $('Gmail Trigger').first().json.From);

// Nombre del remitente: objeto de Telegram o string de Gmail ("Nombre" <mail>)
const nombre_origen = typeof tg === 'object'
  ? tg?.first_name
  : String(tg ?? '').split('<')[0].replace(/"/g, '').trim();

const chat_id = $('input').first().json.chat_id;
const rec = $input.first()?.json ?? {};
const f = rec.fields ?? rec;
const existe = Boolean(rec.id);

let datos = {};
try { datos = JSON.parse(f['Datos clave'] || '{}'); } catch (e) {}

return [{ json: {
  record_id: existe ? rec.id : '',
  Session_ID: chat_id,
  user_name: datos.nombre || nombre_origen || 'Usuario',
  status: f['Estado del proceso'] || 'En progreso',
  last_summary: existe ? (f['Resumen de la conversacion'] || '') : '',
  message_count: existe ? (Number(f['Mensajes']) || 0) : 0,
  datos_clave: JSON.stringify(datos),
}}];

const ctx   = $('Formatear historial').first().json;
const inp   = $('input').first().json;
const final = $input.first().json;
const norm  = $('Normalizacion contrato router').first().json;

const turnos = (ctx.turnos || []).slice(-4);
const historial = [
  ...turnos.map(t => `Usuario: ${t.human ?? ''}\nAsistente: ${t.ai ?? ''}`),
  `Usuario: ${inp.original_input}\nAsistente: ${final.respuesta}`,
].join('\n\n');

const message_count = (Number(ctx.message_count) || 0) + 1;

return [{ json: {
  ...final,
  chat_id: inp.chat_id,
  original_input: inp.original_input,
  user_name: norm.nombre || ctx.user_name,
  datos_clave: norm.datos_clave,
  last_summary: ctx.last_summary,
  historial,
  message_count,
  summarize: message_count % 5 === 0,
}}];

const base = $('Contar mensajes del chat').first().json;
const raw = $json.text ?? $json.output ?? $json.response ?? '';
let d;
try {
  d = JSON.parse(String(raw).replace(/^```json\s*/i,'').replace(/```$/,'').trim());
} catch (e) {
  d = { asunto_principal: base.last_summary, puntos_clave: [], accion_requerida: '', estado_caso: '' };
}
const resumen = [d.asunto_principal, ...(Array.isArray(d.puntos_clave) ? d.puntos_clave : []), d.accion_requerida]
  .filter(Boolean).join(' | ');
return [{ json: {
  ...base,
  resumen_consolidado: resumen || base.last_summary,
  estado_caso: d.estado_caso || 'En progreso',
  fecha_actualizacion: new Date().toISOString(),
}}];

return $input.all().map(i => {
  const j = i.json;
  const norm = $('Normalizacion contrato router').first().json;
  const fallback = [norm.problema && `Problema en curso: ${norm.problema}`, norm.client && `Cliente: ${norm.client}`]
    .filter(Boolean).join(' | ');
  return { json: {
    ...j,
    resumen_consolidado: j.last_summary || fallback || 'Sin resumen aún',
    fecha_actualizacion: new Date().toISOString(),
  }};
});

// Normaliza la salida del Chat Memory Manager (items {human, ai} o {messages:[...]})
let turnos = [];
for (const { json: j } of $input.all()) {
  if (Array.isArray(j.messages)) turnos.push(...j.messages);
  else if (j.human !== undefined || j.ai !== undefined) turnos.push(j);
}
turnos = turnos.filter(t => t && (t.human || t.ai)).slice(-5);
const historial_previo = turnos
  .map(t => `Usuario: ${t.human ?? ''}\nAsistente: ${t.ai ?? ''}`)
  .join('\n\n');
return [{ json: {
  ...$('Contexto Memoria').first().json,
  turnos,
  historial_previo: historial_previo || 'Sin interacciones previas',
}}];

